// ChatApp.jsx
import React, { useEffect, useState } from "react";

const ChatApp = () => {
  const [chatId, setChatId] = useState("");
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const [history, setHistory] = useState([]);

  const user_id = localStorage.getItem("user_id");
  const user_email = localStorage.getItem("user_email");

  useEffect(() => {
    fetch(`http://localhost:8000/chat_history/${user_id}`)
      .then((res) => res.json())
      .then((data) => {
        setHistory(data.history || []);
      });
  }, [user_id]);

  const startNewChat = async () => {
    const res = await fetch("http://localhost:8000/new_chat", {
      method: "POST",
    });
    const data = await res.json();
    setChatId(data.chat_id);
    setMessages([]);
  };

  const sendMessage = async () => {
    if (!input.trim()) return;

    const res = await fetch("http://localhost:8000/chat", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        user_id,
        user_email,
        chat_id: chatId,
        message: input,
      }),
    });

    const data = await res.json();
    setMessages((prev) => [...prev, { user: input, bot: data.response }]);
    setInput("");
  };

  return (
    <div style={{ display: "flex", height: "100vh" }}>
      <aside style={{ width: "250px", background: "#f4f4f4", padding: "1rem" }}>
        <button onClick={startNewChat}>+ New Chat</button>
        <h3>Chat History</h3>
        <ul>
          {history.map((h, i) => (
            <li key={i}>{h.chat_id}</li>
          ))}
        </ul>
      </aside>
      <main style={{ flex: 1, padding: "1rem" }}>
        <div
          style={{
            height: "80vh",
            overflowY: "scroll",
            border: "1px solid #ccc",
            padding: "1rem",
          }}
        >
          {messages.map((msg, i) => (
            <div key={i}>
              <strong>You:</strong> {msg.user}
              <br />
              <strong>AI:</strong> {msg.bot}
              <hr />
            </div>
          ))}
        </div>
        <div style={{ marginTop: "1rem" }}>
          <input
            style={{ width: "80%" }}
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && sendMessage()}
          />
          <button onClick={sendMessage}>Send</button>
        </div>
      </main>
    </div>
  );
};

export default ChatApp;
